            long profit = price - inventory->GetBoughtPrice(itemDefIndex);
            if (profit >= 0) {
                text = bank.GetTextBySymbol(miscDef->TradeProfitString.ToCharString()) + miscDef->ColonSeparator + miscDef->SpaceSeparator + GFIntToWideString(profit);
